"""Vendor SDK for the promotions engine (PromoHub). Vendored as shipped: do not edit this file.

The SDK is synchronous. Each call does one blocking HTTPS round trip to the promotions engine;
locally the round trip is simulated with time.sleep so you can reproduce production latency.
"""

from __future__ import annotations

import os
import time


class PromotionsError(Exception):
    pass


class PromotionsTimeout(PromotionsError):
    pass


_BADGES = {
    "KO-TENT-2P": "Holiday deal: 15% off",
    "KO-BAG-20F": "Bundle with a pad, save $20",
    "KO-LAMP-1": "Members: 2 for $60",
    "KO-PACK-45": "Holiday deal: 10% off",
    "KO-COOL-45": "Free shipping",
}


class PromotionsClient:
    """Blocking client. latency_s simulates the engine's response time."""

    def __init__(self, latency_s: float | None = None, fail: bool = False) -> None:
        if latency_s is None:
            latency_s = float(os.environ.get("PROMO_LATENCY_S", "0.25"))
        self.latency_s = latency_s
        self.fail = fail
        self.calls = 0

    def badges_for(self, skus: list[str], timeout: float | None = None) -> dict[str, str]:
        """Return {sku: badge text} for skus that have an active promotion.

        Blocks the calling thread for the round trip. With timeout set, gives up after
        `timeout` seconds and raises PromotionsTimeout.
        """
        self.calls += 1
        if timeout is not None and self.latency_s > timeout:
            time.sleep(timeout)
            raise PromotionsTimeout(f"promotions engine did not answer within {timeout}s")
        time.sleep(self.latency_s)
        if self.fail:
            raise PromotionsError("promotions engine returned HTTP 503")
        return {s: _BADGES[s] for s in skus if s in _BADGES}
